public class InnerSecurityConfigurationAuthenticationConfigurationFactory(Action<Humidifier.EMRContainers.SecurityConfigurationTypes.AuthenticationConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.SecurityConfigurationTypes.AuthenticationConfiguration>
{

    internal InnerSecurityConfigurationIAMConfigurationFactory IAMConfigurationFactory { get; set; }

    internal InnerSecurityConfigurationIdentityCenterConfigurationFactory IdentityCenterConfigurationFactory { get; set; }

    protected override Humidifier.EMRContainers.SecurityConfigurationTypes.AuthenticationConfiguration Create()
    {
        var authenticationConfigurationResult = CreateAuthenticationConfiguration();
        factoryAction?.Invoke(authenticationConfigurationResult);

        return authenticationConfigurationResult;
    }

    private Humidifier.EMRContainers.SecurityConfigurationTypes.AuthenticationConfiguration CreateAuthenticationConfiguration()
    {
        var authenticationConfigurationResult = new Humidifier.EMRContainers.SecurityConfigurationTypes.AuthenticationConfiguration();

        return authenticationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.SecurityConfigurationTypes.AuthenticationConfiguration result)
    {
        base.CreateChildren(result);

        result.IAMConfiguration ??= IAMConfigurationFactory?.Build();
        result.IdentityCenterConfiguration ??= IdentityCenterConfigurationFactory?.Build();
    }

} // End Of Class

